"""Individually read remaining mm/util.c mechanisms; pending authored lessons."""
def register(topic,q,detail):
    topic('VMA 보조·Stack 주소와 File 참조 교체','메모리','mm/util.c','vma_set_file',
      '가상 주소 구간과 backing file을 연결할 때 자료 필드 대입과 참조 수명 처리가 함께 필요합니다.',
      'vma_set_file은 새 file을 get_file한 뒤 vm_file과 local file을 swap하고 이전 file을 fput합니다. 원본은 초기 VMA 설정 중에만 유효하고 anonymous VMA를 이 방식으로 바꾸면 안 된다고 명시합니다. vma_is_stack_for_current는 현재 stack pointer가 vm_start 이상·vm_end 이하인지 비교하는 보조 판정입니다.',
      '초기 설정과 file 수명 조건을 지켜 사용합니다. 살아 있는 임의 VMA를 단순 pointer 변경으로 다른 mapping으로 전환하지 않습니다. Stack helper의 inclusive 비교를 다른 VMA 탐색 API의 일반 end-exclusive 계약으로 대체하지 않습니다.',
      'get_file→swap→fput과 KSTK_ESP의 두 비교를 읽으세요.',
      q('새 file을 대입하기 전에 get_file하는 이유는?', '새 backing file의 참조 수명을 확보한다', '기존 file 이름을 바꾸기 위해', '새 참조를 얻고 이전 참조는 swap 뒤 fput합니다. 자료 대입과 객체 수명은 함께 처리합니다.'),
      q('anonymous VMA를 이 helper만으로 file mapping으로 바꾸는가?', '원본 계약이 금지한다', '모든 VMA 전환이 자동 처리된다', '이 함수는 초기 설정에서 file 참조를 교체하는 작은 helper입니다. Anonymous mapping의 구조 전체를 바꾸는 API가 아닙니다.'),
      details=[detail('처음 읽는 용어','VM은 가상 메모리, VMA는 한 프로세스의 가상 주소 구간입니다. mm은 그 프로세스의 메모리 정보를 담는 객체입니다. Page는 기본 메모리 단위이고 folio는 하나 이상의 page를 함께 관리하는 묶음입니다. Allocator는 저장 공간을 할당하는 기능이며 참조 수는 객체가 언제까지 살아 있어야 하는지를 관리합니다.'),detail('Swap 이후 Local','swap 뒤 local file에는 이전 vm_file이 있습니다. fput(file)은 새 객체가 아니라 교체한 이전 참조를 내려놓습니다.'),detail('Stack 경계','이 원본 helper는 vm_end>=stack_pointer입니다. 정확한 구현 비교와 다른 API의 주소 구간 계약을 구분하며 일반 VMA 존재 검색을 이 함수로 대신하지 않습니다.'),detail('파일 전체의 연결','mm/util.c는 문자열·사용자 복제, VMA·주소 배치, 회계, KV allocation, folio, overcommit, 명령행, page 진단과 offline 동기화의 보조 기능을 담습니다. Includes는 mm·slab·vmalloc·uaccess·task·security·swap 타입과 API를 연결합니다. EXPORT_SYMBOL과 GPL export는 모듈 연결, KUnit export는 선택 시험 연결이며 weak는 architecture 대체를 허용합니다. User bucket의 subsys init은 자원을 설정한 뒤0을 반환하고 __ro_after_init 표식을 사용합니다.')])
    topic('Stack ASLR·Page Mask와 성장 방향','메모리','mm/util.c','randomize_stack_top',
      '프로세스 stack 시작을 page 단위로 움직이는 주소 무작위화에서 flag와 architecture 성장 방향을 읽습니다.',
      'PF_RANDOMIZE가 있으면 get_random_long의 낮은 STACK_RND_MASK bit를 남기고 PAGE_SHIFT만큼 왼쪽 이동합니다. 없으면 random_variable은0입니다. 기본 mask는 page 크기에 따라 조정됩니다. PAGE_ALIGN(stack_top) 뒤 위로 자라는 설정은 더하고 일반 아래로 자라는 설정은 뺍니다.',
      '선택 architecture·page 크기·personality의 randomization 설정을 함께 확인합니다. 반환은 주소 배치 후보이며 그 범위에 실제 memory를 allocation하는 함수는 아닙니다. 난수 폭과 page alignment를 byte 수·entropy bit로 구분합니다.',
      'PF_RANDOMIZE·mask·shift·CONFIG_STACK_GROWSUP의 +/-를 읽으세요.',
      q('PF_RANDOMIZE가 없으면 난수 함수가 이 branch에서 호출되는가?', '호출 없이0 offset이다', '언제나 같은 수의 난수를 소비한다', '난수 생성은 flag 조건 안에 있습니다. Alignment 처리와 random offset을 분리합니다.'),
      q('PAGE_SHIFT 이동의 목적은?', '선택한 page 개수를 byte offset으로 바꾼다', '항상 난수 bit를 모두 버린다', 'page 크기2^PAGE_SHIFT를 곱하는 shift입니다. 주소 이동이 page 단위가 됩니다.'),
      details=[detail('성장 방향','위로 자라는 stack은 더하는 branch, 아래로 자라는 stack은 빼는 branch입니다. 모든 Linux architecture가 같은 stack 배치를 쓴다고 설명하지 않습니다.'),detail('Page Alignment','PF_RANDOMIZE가 없어도 PAGE_ALIGN(stack_top)은 적용됩니다. Randomization을 끄는 것과 입력 byte 주소를 그대로 반환하는 것은 다릅니다.')])
    topic('Randomize Page·정렬과 Range 한도','메모리','mm/util.c','randomize_page',
      '허용 주소 범위에서 page 정렬 후보를 선택하며 unsigned 산술과 caller의 입력 조건을 확인합니다.',
      'start가 unaligned이면 다음 page까지의 차이를 range에서 빼고 start를 올려 정렬합니다. start+range overflow가 가능하면 range를 ULONG_MAX-start로 줄입니다. range를 PAGE_SHIFT만큼 오른쪽 이동해 page 개수를 만들고0이면 start, 아니면 get_random_long()%range를 page offset으로 바꿔 더합니다.',
      'Alignment 차이를 감당할 수 있는 충분한 range를 제공합니다. 아주 작은 range는 첫 unsigned 뺄셈에서 underflow할 수 있으므로 이 helper가 모든 잘못된 범위를 자동 거부한다고 생각하지 않습니다. Modulo 선택을 편향 없는 암호학적 균등 난수 증명으로 확대하지 않습니다.',
      '정렬 차이 뺄셈·overflow cap·page 수0·modulo를 읽으세요.',
      q('정렬 후 range가 한 page 미만이면?', 'page 수0이어서 정렬된 start를 반환한다', '한 page를 무조건 allocation한다', 'shift 뒤0이면 조기 반환합니다. Mapping이나 allocation은 수행하지 않습니다.'),
      q('시작 정렬에 필요한 차이보다 range가 작아도 안전한 거부가 보장되는가?', 'caller가 범위 조건을 보장해야 한다', '첫 뺄셈에 언제나 EINVAL 검사가 있다', '원본은 unsigned range에서 차이를 직접 뺍니다. 이 분기에 오류 코드 검사는 없습니다.'),
      details=[detail('Overflow와 Alignment','뒤쪽 start>ULONG_MAX-range 검사는 덧셈 overflow cap입니다. 앞쪽 정렬 뺄셈의 입력 전제까지 같은 검사로 해결했다고 설명하지 않습니다.'),detail('Modulo의 한계','난수 공간 크기가 page 수로 나누어떨어지지 않으면 modulo 결과 분포에 작은 편향이 생길 수 있습니다. 이 source에는 rejection sampling loop가 없습니다.')])
    topic('Mmap 배치 선택·Legacy와 Top Down','메모리','mm/util.c','arch_pick_mmap_layout',
      '같은 mmap 호출도 프로세스 설정과 stack 제한에 따라 탐색 시작과 방향이 달라지는 이유를 배웁니다.',
      'PF_RANDOMIZE이면 arch_mmap_rnd로 page random factor를 만듭니다. ADDR_COMPAT_LAYOUT·아래로 자라는 무제한 stack·legacy sysctl 조건이면 TASK_UNMAPPED_BASE+random에서 시작하고 MMF_TOPDOWN을 지웁니다. 그렇지 않으면 mmap_base가 stack limit·guard gap·random pad를 고려해 주소를 계산하고 TOPDOWN을 설정합니다. 별도 MMU fallback은 기본 base와 clear만 수행합니다.',
      'CONFIG의 기본 topdown 선택과 compat task·mmap_rnd bits를 확인합니다. 주소 배치 정책과 실제 빈 VMA 검색·mapping allocation을 구분합니다. Stack growsup은 gap 계산의 별도 branch입니다.',
      'legacy 조건·mmap_base·MMF_TOPDOWN set/clear·대체 CONFIG 경로를 읽으세요.',
      q('Legacy 배치에서 MMF_TOPDOWN은?', 'clear된다', '항상 set된다', '원본은 legacy branch에서 clear_bit를 호출합니다. Base와 방향 flag를 함께 갱신합니다.'),
      q('일반 topdown의 gap 계산은 stack 제한만 쓰는가?', 'guard gap과 필요시random pad도 고려한다', '항상0 gap으로 시작한다', 'mmap_base는 rlim_cur에 guard와 randomization 공간을 고려하고 최소·최대 gap으로 제한합니다.'),
      details=[detail('Gap 경계','일반 down-stack 계산의 최소는128MiB, 최대는 STACK_TOP의5/6입니다. 큰 limit에 pad를 더할 때 조건부 overflow 회피를 두고 정렬된 base를 반환합니다.'),detail('Compat Random','arch_mmap_rnd는 지원 설정에서 compat task의 별도 bit 수를 선택하고 PAGE_SHIFT로 바꿉니다. arch_randomize_brk도 compat·32bit는32MiB, 일반64bit는1GiB 범위를 사용합니다.'),detail('위로 성장','CONFIG_STACK_GROWSUP의 mmap_base는 mmap_upper_limit에서 random을 빼고 아래로 정렬합니다. 일반 down-stack 공식과 같은 것으로 추정하지 않습니다.'),detail('대체와 시험 연결','arch_randomize_brk는 weak 기본 구현이며 architecture가 바꿀 수 있습니다. MMU 설정에서는 arch_pick_mmap_layout을 KUnit에 export합니다. 약한 기본 정의와 시험 연결이 별도 알고리즘이라고 수를 늘리지 않습니다.')])
    topic('Locked VM 회계·쓰기 Lock과 Memlock 한도','메모리','mm/util.c','__account_locked_vm',
      '잠근 page 수의 회계에서 byte 단위 제한과 page 단위 counter를 연결하고 실패 시 갱신을 막습니다.',
      '__account_locked_vm은 mmap write lock을 요구합니다. 증가 때 bypass가 아니면 RLIMIT_MEMLOCK을 PAGE_SHIFT로 나눠 limit과 locked_vm+pages를 비교합니다. 넘으면ENOMEM, 정상일 때만 counter를 갱신합니다. 감소는 pages>locked_vm을 WARN하지만 뺄셈은 실행합니다. Wrapper account_locked_vm은 NULL mm·0page면0이며 lock을 잡고 current·CAP_IPC_LOCK bypass를 전달합니다.',
      'Mm·task 참조 수명을 유지하고 직접 helper에는 write lock을 보장합니다. 증가 합·감소 범위는 caller가 올바른 page 회계로 관리합니다. WARN이 잘못된 감소를 되돌리는 exception이라고 생각하지 않습니다. Privilege bypass와 memory 접근 권한을 구분합니다.',
      'limit shift·ret 조건·counter 대입·wrapper lock/unlock을 읽으세요.',
      q('한도를 넘는 증가에서 locked_vm은?', '기존 값을 보존하며ENOMEM', '일단 늘리고 항상 성공', 'ret가0일 때만 증가를 대입합니다. 검사와 갱신이 같은 write lock 안에 있어야 합니다.'),
      q('감소 pages가 counter보다 클 때 WARN만으로 뺄셈이 취소되는가?', 'WARN 뒤에도 뺄셈하므로 caller의 범위 보장이 필요하다', '자동으로 0에 제한된다', '원본은 경고 다음 locked_vm-pages를 대입합니다. 임의 잘못된 감소를 안전하게 보정하는 API가 아닙니다.'),
      details=[detail('단위','RLIMIT는 byte, counter와pages는 page입니다. Shift로 limit 단위를 맞추며 debug 출력은 page를 다시 byte로 바꿉니다.'),detail('Wrapper 경로','Wrapper는 현재 task의 capability를 확인합니다. NULL mm와0page를 정상 no-op으로 처리하지만 내부 helper의 참조·lock 전제는 그대로입니다.')])
    topic('Kernel Mmap Wrapper·Security와 Lock 이후 처리','메모리','mm/util.c','vm_mmap_pgoff',
      'Mapping 생성 앞 권한 검사와 뒤 population·userfault 통지가 lock 범위와 어떻게 연결되는지 읽습니다.',
      'security_mmap_file이 성공해야 killable mmap write lock을 잡습니다. Lock 실패는EINTR입니다. do_mmap은 pgoff와 populate·userfault list를 전달받고 반환 뒤 lock을 풀어 userfaultfd_unmap_complete를 호출합니다. populate가 있으면 mm_populate입니다. vm_mmap의 byte offset은 alignment·offset+PAGE_ALIGN(len) overflow 조건을 확인한 뒤 page offset으로 바뀝니다.',
      '원본의 unsigned long 반환이 성공 주소 또는 음수 errno 표현임을 확인하고 실제 caller의 오류 판정을 사용합니다. Wrapper 검사만으로 모든 len·주소·flag 문법이 완료됐다고 생각하지 않고 do_mmap 검증도 추적합니다. Userfault 완료와 population을 lock을 잡은 상태로 임의 재배치하지 않습니다.',
      'security→killable lock→do_mmap→unlock→완료→population 순서를 읽으세요.',
      q('Security hook이 오류이면 do_mmap을 호출하는가?', '호출하지 않고 그 오류를 반환한다', '일단mapping을만든뒤검사한다', '전체 mapping branch는 ret0 조건 안입니다. Permission 검사와 생성 순서를 지킵니다.'),
      q('Userfault 완료와 population은 write lock의 안인가?', 'unlock 뒤에 실행한다', '항상같은lock을계속잡는다', '원본은 do_mmap 뒤 먼저 unlock합니다. 후속 처리의 동기화·sleep 계약을 순서와 연결합니다.'),
      details=[detail('Offset 단위','vm_mmap은 byte offset의 page alignment를 검사하고 >>PAGE_SHIFT한pgoff를 전달합니다. 두 함수의 offset 단위가 다릅니다.'),detail('오류와 주소','Unsigned 반환에 음수 errno가 표현될 수 있습니다. 큰 수라는 이유만으로 정상 높은 mapping 주소로 사용하지 않습니다. 정확한 오류 판정은 이 API의 caller 계약을 따릅니다.')])
    topic('KVMalloc 대체 경로·GFP와 Page 크기','메모리','mm/util.c','__kvmalloc_node_noprof',
      '먼저 물리 연속 allocation을 시도하고 실패할 때 가상 연속 allocation으로 바꾸는 조건을 익힙니다.',
      '먼저 __kmalloc_node_noprof를 호출합니다. 성공 또는 요청이 PAGE_SIZE 이하이면 그대로 반환합니다. 큰 요청 실패에서 blocking을 허용하지 않는 flags면NULL, INT_MAX 초과면 경고 조건 뒤NULL입니다. 나머지는 VM_ALLOW_HUGE_VMAP을 주어 vmalloc range로 갑니다. kmalloc_gfp_adjust는 큰 요청에 NOWARN·필요시NORETRY를 추가하고 NOFAIL을 지웁니다.',
      '수면 가능한 GFP_KERNEL 호환 context와 적절한 크기를 제공합니다. 결과의 물리 연속을 가정하지 않고 kvfree합니다. Retry 정책은 첫 kmalloc 시도와 vmalloc fallback을 나눠 읽습니다. Atomic allocation에 임의 fallback을 기대하지 않습니다.',
      '첫 시도·page 한도·blocking·INT_MAX·vmalloc의 순서를 읽으세요.',
      q('작은 요청의 kmalloc이 실패하면 vmalloc도 항상 시도하는가?', 'PAGE_SIZE 이하이면 바로 반환한다', '모든크기에서무조건fallback한다', 'ret 또는 size<=PAGE_SIZE 조건에서 반환합니다. 작은 allocation의 별도 vmalloc을 피합니다.'),
      q('성공 결과의 해제로 선택할 공통 함수는?', 'kvfree', '물리연속만보장해항상kfree', '성공이 kmalloc 또는 vmalloc 경로일 수 있습니다. kvfree가 주소 계열에 맞춰 정리합니다.'),
      details=[detail('큰 요청 Flags','NOWARN으로 첫 실패 경고를 줄이고 RETRY_MAYFAIL이 없으면NORETRY를 추가합니다. NOFAIL은 첫 kmalloc에서 지우며 원본 주석은 fallback의 의미를 설명합니다.'),detail('Huge Vmap 선택','Fallback은 VM_ALLOW_HUGE_VMAP을 사용합니다. 결과 pointer를 얻었다고 실제 모든 요청이 huge page로 만들어졌다는 보장은 아닙니다.'),detail('원래 Flags','Blocking 검사와 fallback에는 원래 flags를 사용합니다. 첫 allocator에 전달한 조정 flags와 별도 변수임을 읽습니다.')])
    topic('KV 해제·주소 계열과 민감 자료 지우기','메모리','mm/util.c','kvfree_sensitive',
      'Allocation 계열에 맞는 해제와 민감 자료의 명시적 초기화를 같은 수명 종료 순서에 배치합니다.',
      'kvfree는 is_vmalloc_addr이면vfree, 아니면kfree입니다. kvfree_sensitive는 ZERO_OR_NULL_PTR가 아니면 memzero_explicit(addr,len)을 먼저 실행한 뒤kvfree합니다. 정상 pointer의 지정 범위만 지우며NULL·zero-size sentinel은 건너뜁니다.',
      '실제 allocation 길이와 ownership을 보관해 마지막 참조에서 사용합니다. Len이 allocation 밖을 넘지 않도록 보장합니다. Zeroing 이후 다른 thread가 사용하는 자료가 있으면 수명 경쟁이므로 별도 동기화가 필요합니다. 이 해제는NMI context용이 아닙니다.',
      '주소 분기·zero/null guard·wipe→free 순서를 읽으세요.',
      q('민감 자료를 먼저 해제한 뒤 같은 주소를 지우는가?', '지운 뒤 해제한다', '해제 뒤 쓰는 것이 정상이다', '해제 뒤 쓰기는 이미 다른 객체가 사용할 수 있는 영역입니다. 원본은 명시적 초기화를 먼저 합니다.'),
      q('ZERO_SIZE_PTR도 len만큼 무조건 접근하는가?', '특별한 pointer 검사에서 건너뛴다', '항상 정상 buffer처럼 쓴다', 'ZERO_OR_NULL_PTR 조건으로 실제 자료가 없는 특별한 pointer를 분리합니다.'),
      details=[detail('해제 Context','kvfree 문서는 preemptible task 또는 not-NMI interrupt context를 명시합니다. Vmalloc 정리의 실제 context 계약을 확인합니다.'),detail('지정 영역만','memzero_explicit은 compiler 제거를 막는 지정 영역 처리입니다. 모든 복제본·register·장치 cache를 자동 지우는 기능은 아닙니다.')])
    topic('KV 재할당·기존 자료 보존과 실패 Ownership','메모리','mm/util.c','kvrealloc_noprof',
      '자료를 더 큰 공간으로 옮길 때 새 할당 실패가 기존 pointer의 소유권을 없애지 않는 경로를 읽습니다.',
      'Vmalloc 주소이면 vrealloc_noprof에 위임합니다. 아니면 조정 flags로 krealloc을 시도합니다. 실패하면 kvmalloc을 시도하고 또 실패하면NULL입니다. 새 allocation이 성공하고 이전p가 있으면 KASAN을 잠시 비활성화해 tag를 정리한p의 ksize만큼 복사한 뒤 다시 활성화하고 이전p를kfree합니다.',
      '같은 allocation에 재할당·해제를 동시에 호출하지 않습니다. 실패 반환은 기존p를 보관하여 계속 소유해야 합니다. 성공한 반환으로 pointer를 갱신합니다. ZERO 초기화 의미가 필요하면 처음부터 모든 후속 호출에서GFP_ZERO를 유지하라는 문서 조건을 지킵니다.',
      'vmalloc 위임·krealloc·fallback·copy→free·NULL 실패를 읽으세요.',
      q('대체 할당도 실패하면 이전 p를 이미 해제했는가?', '이 경로는 이전 p를 보존한다', '실패 전에 무조건 해제한다', '새allocation 실패는 memcpy와kfree 전에NULL을반환합니다. 실패에서도caller의기존ownership은남습니다.'),
      q('같은 p에 동시에 kvfree와 kvrealloc을 호출해도 되는가?', '문서가 동시 호출을 금지한다', '이 함수가 모든 경쟁을 내부 lock으로 처리한다', '같은allocation에대한동시재할당·해제는허용되지않습니다. Ownership과외부직렬화가필요합니다.'),
      details=[detail('복사 크기','Fallback은 기존 kmalloc 객체의 ksize를 사용합니다. 요청했던 논리 길이와 allocator의 실제 크기를 구분하고 이 경로의 재할당 조건을 임의 작은 새 buffer의 복사 예제로 옮기지 않습니다.'),detail('0 크기','문서는 p=NULL이면 kvmalloc처럼, size 0이며 p가 있으면 해제라고 설명합니다. 실제 0 크기의 반환 표현은 위임하는 allocator 계약과 함께 확인합니다.'),detail('KASAN과 Tag','기존 p의 tag를 리셋하고 복사 동안 KASAN 검사를 조절합니다. 이 분기는 일반 코드가 검사를 임의로 끄라는 사용법이 아닙니다.')])
    topic('Vmalloc Array·곱셈 검사와 Zero Flag','메모리','mm/util.c','__vmalloc_array_noprof',
      '가상 연속 배열의 총 크기를 계산할 때 overflow를 allocation 전에 검사하고 초기화 옵션을 전달합니다.',
      '__vmalloc_array_noprof는 n×size의 check_mul_overflow 실패면 NULL, 성공하면 bytes를 __vmalloc_noprof에 전달합니다. vmalloc_array는 GFP_KERNEL입니다. __vcalloc은 받은 flags에 GFP_ZERO를 OR하고 vcalloc은 GFP_KERNEL|GFP_ZERO입니다. 원소 개수와 한 원소 byte 크기를 곱합니다.',
      'NULL 실패를 검사하고 성공 결과는 해당 vmalloc 해제 계약을 사용합니다. Zero는 allocator에 요청하는 flag이며 이 wrapper에 별도 원소 생성자가 없습니다. Byte 0과 임의 자료형의 논리 초기화를 동일하게 보지 않습니다.',
      'overflowbranch·bytes·defaultflags·ZEROOR를비교하세요.',
      q('곱셈이 overflow되면 잘린 byte 수로 계속 할당하는가?', 'NULL을 먼저 반환한다', '작은 배열로 정상 반환한다', 'check_mul_overflow가true이면allocator를호출하지않습니다. 작게할당하고큰개수를쓰는문제를피합니다.'),
      q('Vcalloc의 기본 flags는?', 'GFP_KERNEL와 __GFP_ZERO', '항상 atomic하고 초기화하지 않는다', '원본은두flag를OR해가상연속allocation에전달합니다.'),
      details=[detail('주변 Wrapper','noprofbody는allocation profiling이없는engine이고공개계열은header의hooks와연결될수있습니다. Profiling과 자료의 초기화 정책을 구분합니다.'),detail('크기 단위','n은 원소 개수, size는 한 원소 byte 수입니다. Pointer 배열을 만들 때 sizeof(pointer)와 가리키는 객체 크기를 혼동하지 않습니다.')])
    topic('Folio Mapping·Pointer Tag와 Swap 우선순위','메모리','mm/util.c','folio_mapping',
      'Page 묶음의 mapping field가 항상 정상 주소인 것은 아니라는 tagged pointer 원리를 읽습니다.',
      'folio_anon_vma는 mapping의 PAGE_MAPPING_FLAGS가 정확히 ANON인지 확인하고 표식 값을 빼서 anon_vma를 반환합니다. folio_mapping은 slab이면 NULL, swapcache면 swap_address_space로 갑니다. 나머지 mapping에 flag bit가 있으면 NULL이며 일반 pagecache mapping만 반환합니다.',
      'Folio의 수명과 상태 동기화를 보장하고 반환 NULL을 처리합니다. Folio mapping과 사용자 VMA 주소를 같은 pointer로 보지 않습니다. Swapcache의 mapping은 swap 파일 자체의 mapping과 다르다는 문서 조건도 확인합니다.',
      'flagmask·정확한ANON비교·slab→swap→일반mapping순서를읽으세요.',
      q('mapping 필드에 표식 bit가 있어도 항상 address_space로 읽는가?', '상태에 따라 NULL 또는 별도 mapping으로 분기한다', '모든 bit가 정상 pointer 주소다', 'tagbit를판별하는분기가있습니다. 표현과pointer대상을구분합니다.'),
      q('Swapcache folio는 어느 mapping을 반환하는가?', 'swap_address_space의 mapping', '항상 일반 파일의 page cache mapping', 'Swapcache분기는일반mapping검사보다먼저입니다. Swap저장의회계mapping계약을사용합니다.'),
      details=[detail('정확한 Tag','ANON bit만 있는지 전체 PAGE_MAPPING_FLAGS mask로 비교합니다. ANON이 포함됐다는 단순 bit 검사와 동일한 조건이 아닙니다.'),detail('Slab 예외','Slab folio를 일반 pagecache로 해석하지 않도록 NULL을 반환합니다. Flush 경로에서 다른 종류 page가 들어오는 경우를 주석이 설명합니다.')])
    topic('Folio 복사·Page 반복과 중간 Poison 오류','메모리','mm/util.c','folio_mc_copy',
      '여러 page의 자료를 복사할 때 reschedule 위치와 중간 오류의 부분 결과를 읽습니다.',
      'folio_copy는 source page 수만큼 copy_highpage를 반복하고 마지막이 아니면 cond_resched합니다. folio_mc_copy는 copy_mc_highpage가 실패하면 EHWPOISON으로 즉시 반환합니다. 성공한 앞 page를 되돌리는 rollback은 없습니다. 마지막 page 뒤에는 cond_resched를 추가하지 않습니다.',
      '목적 folio가 source 이상 크기임을 caller가 검사합니다. Order 0은 atomic context에서 가능하지만 큰 folio는 sleep할 수 있다는 문서를 따릅니다. Poison 오류에서 목적을 완전한 복제본으로 공개하지 않고 부분 결과 정책을 처리합니다.',
      'nr·i증가·마지막break·cond_resched·오류조기반환을읽으세요.',
      q('두 번째 page 복사가 실패하면 첫 page는 자동 원상 복구되는가?', '복사된 부분은 남을 수 있다', '함수가 전체 결과를 되돌린다', '오류branch에역방향복사나초기화가없습니다. Caller가부분결과와공개정책을처리해야합니다.'),
      q('한 page folio 복사에서도 반복 끝에 reschedule하는가?', '마지막 break가 먼저라 하지 않는다', '무조건 한 번 잠든다', '++i==nr이면cond_resched전에break합니다. 문서의order0context계약과연결합니다.'),
      details=[detail('목적 크기','복사 loop는 source의 nr page를 기준으로 합니다. 목적의 충분한 크기를 이 body가 직접 검사하지 않으므로 caller 전제가 필요합니다.'),detail('오류 의미','EHWPOISON은 machine-check copy에서 문제 자료를 읽지 못한 경로입니다. 단순 allocation ENOMEM과 같은 원인으로 설명하지 않습니다.')])
    topic('Overcommit 정책 교체·Batch와 Per CPU 동기화','메모리','mm/util.c','overcommit_policy_handler',
      '느슨한 메모리 회계를 엄격한 정책으로 바꿀 때 공개 순서를 조절해 남은 CPU별 값을 합칩니다.',
      'Write이면 임시 table.data를 new_policy에 연결해 minmax parser로 읽습니다. 오류나 값 미설정이면 반환합니다. 정상 정책에는 먼저 mm_compute_batch를 적용하고 NEVER로 바꾸면 schedule_on_each_cpu(sync_overcommit_as)로 각 CPU counter를 동기화합니다. 마지막에 sysctl_overcommit_memory를 대입합니다. Read는 기존 table을 parser에 전달합니다.',
      '정책 값을 정상 sysctl 인터페이스로 변경하고 회계 batch·CPU별 누적·전역 정책의 순서를 이해합니다. 전역 변수만 직접 대입해 동일 전환이 처리됐다고 생각하지 않습니다. 이 helper의 CPU 동기화를 임의 객체 수명 보호나 모든 memory barrier로 쓰지 않습니다.',
      '임시 new_policy·batch→percpu sync→publish·read branch를 읽으세요.',
      q('NEVER 정책 전환의 실제 순서는?', 'batch 조정·각CPU counter 동기화·정책 공개', '정책 공개 뒤아무검사없이종료', '원본 주석은 느슨한 회계의 오차를 줄인 뒤 엄격한 정책을 공개하려는 순서를 설명합니다.'),
      q('Read 호출에서도 항상 정책을 새로 대입하는가?', '읽기는 기존 table을 parser에 전달한다', '모든 조회가 정책을 바꾼다', 'write 조건 안에서만 임시 값과 전환 경로를 사용합니다. 조회와 변경을 구분합니다.'),
      details=[detail('동기화 Callback','sync_overcommit_as는 percpu_counter_sync(&vm_committed_as)를 호출합니다. CPU별 미반영 값을 전역 회계와 맞추는 목적입니다.'),detail('두 한도 설정','overcommit_ratio_handler는 정상 write에서 kbytes를0, overcommit_kbytes_handler는 정상 write에서 ratio를0으로 합니다. 읽기나 parser 오류에는 다른 설정을 지우지 않습니다.')])
    topic('Commit Limit·RAM·Huge Page·Swap의 단위','메모리','mm/util.c','vm_commit_limit',
      '메모리 예약 허용 한도가 실제 현재 물리 사용량과 다르다는 점을 page 단위 공식으로 익힙니다.',
      'overcommit_kbytes가 있으면 PAGE_SHIFT-10으로 나눠 page 수를 구합니다. 아니면 totalram_pages-hugetlb_total_pages에 ratio를 곱해100으로 나눕니다. 마지막에 total_swap_pages를 더합니다. vm_memory_committed는 vm_committed_as의 positive sum을 반환하며 counter는 SMP cacheline에 별도 정렬됩니다.',
      '한도의 단위를 page로 맞춰 비교하고 reservation 회계와 실제 resident memory를 구분합니다. Huge page를 제외하는 이유와 swap 추가를 공식에 연결합니다. 전역 변수의 초기 ratio50·user reserve128MiB·admin reserve8MiB는 이 고정 버전의 기본 값이며 runtime 설정을 따로 읽습니다.',
      'kbytes branch·RAM-huge·ratio/100·swap 추가·positive sum을 읽으세요.',
      q('kbytes 설정이 있으면 ratio 공식도 더하는가?', '둘 중 한 경로를 선택하고 swap을 더한다', 'kbytes와 ratio를 항상 둘 다 더한다', 'if/else는 대체 방식입니다. 두 한도 값을 중복 더하지 않습니다.'),
      q('vm_memory_committed의 값은 현재 RSS와 항상 같은가?', '예약 회계 counter의 합이다', '모든 프로세스 RSS 그 자체다', 'Committed 회계와 실제 resident memory는 다른 측정값입니다. 이 함수는 percpu commitment counter를 합칩니다.'),
      details=[detail('Kb에서 Page','PAGE_SHIFT12라면 kbytes를2bit 오른쪽 이동해4KiB page 개수로 바꿉니다. 원래 KB 수와 page 수를 바로 비교하지 않습니다.'),detail('Counter와 Cacheline','여러CPU가 자주 갱신하는 counter를 다른 변수와 cacheline을 공유하지 않도록 정렬합니다. Positive sum과 빠른 batched read의 비용·오차 계약은 다릅니다.'),detail('기본 변수와 표식','sysctl_max_map_count는 DEFAULT_MAX_MAP_COUNT로 시작하는 VMA 수 한도 설정입니다. 별도 initializer가 없는 kbytes 변수는 C의 정적 초기화로0입니다. __read_mostly는 읽기 중심 배치 표식이고 read-only 권한이나 불변 값의 보장은 아닙니다. 실제 설정 변경은 각 sysctl 경로를 따릅니다.')])
    topic('메모리 예약 허용·먼저 회계하고 실패 복원','메모리','mm/util.c','__vm_enough_memory',
      '요청을 예약 회계에 더한 뒤 정책별로 승인하거나 되돌리는 과정을 단계별로 읽습니다.',
      '먼저 vm_acct_memory(pages)를 실행합니다. ALWAYS는 성공, GUESS는 요청 pages가 RAM+swap보다 크면 실패입니다. 엄격 경로는 commit limit에서 비관리자 reserve와 process total_vm/32·user reserve 중 작은 값을 뺍니다. Positive committed read가 allowed보다 작아야 성공입니다. 실패는 경고 후 vm_unacct_memory로 요청을 반납하고ENOMEM입니다.',
      '이 helper의 승인과 실제 page allocation 성공을 구분합니다. Policy·cap_sys_admin·mm 유무를 올바르게 전달하고 예약 회계의 다른 단계와 중복 증가·감소하지 않습니다. 엄격 비교가 <=가 아니라 <임을 문제에서 확인합니다.',
      'acct→정책분기→reserve→strict 비교→unacct를 읽으세요.',
      q('엄격한 분기에서 회계값이 allowed와 정확히 같으면?', '작지 않으므로 실패 경로다', '같으면 언제나 성공이다', '원본 조건은 positive counter<allowed입니다. 경계값을 다른 inequality로 바꾸지 않습니다.'),
      q('승인 실패에서도 앞의 예약 증가를 계속 남기는가?', 'vm_unacct_memory로 되돌린다', '모든 실패가 예약 누적으로 남는다', '공통 error 경로는 요청 pages를 반납합니다. 사전 회계와 실패 정리를 한 쌍으로 읽습니다.'),
      details=[detail('GUESS의 실제 조건','이 원본의 GUESS 분기는 이번 요청 pages를 전체 RAM+swap과 비교합니다. 기존 모든 commitment를 엄격하게 비교하는 NEVER 공식과 같은 경로가 아닙니다.'),detail('Reserve의 두 종류','비관리자에는 admin reserve를 빼고 mm가 있으면 total_vm/32와 user reserve 중 작은 값도 뺍니다. NULL mm면 두 번째 process reserve는 적용하지 않습니다.'),detail('승인과 물리 공급','회계승인은 주소공간·메모리예약 정책의 검사입니다. 이후 실제 물리 page나 다른 kernel 자원을 얻는 작업은 별도로 실패할 수 있습니다.')])
    topic('Get Cmdline·범위 Snapshot과 종료 보정','프로세스','mm/util.c','get_cmdline',
      '다른 task의 명령행을 읽을 때 mm 참조와 주소 범위 lock을 보관하되 최종 내용이 원자 snapshot은 아닌 이유를 배웁니다.',
      'get_task_mm으로 참조를 얻고 mm가 없거나 arg_end가 아직0이면0입니다. arg_lock으로 arg·env 범위를 복사한 뒤 풀고 access_process_vm으로 buflen 한도 안을 읽습니다. 마지막 NUL이 덮이고 아직 공간이 있으면 내부 NUL까지 길이를 줄이거나 env 영역을 이어 읽어 strnlen으로 제한합니다. 모든 mm 경로는 mmput합니다.',
      '실제 writable 목적과 nonnegative 길이를 제공합니다. 반환 byte 수를 사용하고 끝 NUL 보장이 없으므로 문자열 출력은 caller가 공간을 남겨 종료합니다. User가 argument 내용을 바꿀 수 있어 범위 snapshot과 전체 byte 일관성을 구분합니다.',
      'mm 참조·arg_lock·읽기·덮인NUL branch·mmput을 읽으세요.',
      q('반환 자료는 항상 끝의 NUL을 보장하는가?', '문서상 보장하지 않는다', '어떤 한도에서도 항상 추가한다', '원본은 크기만 반환합니다. 앞 quotable_cmdline caller는 한 칸을 남겨 자체 종료를 삽입했습니다.'),
      q('범위 조회 lock을 풀고 자료를 읽어도 전체 내용이 하나의 원자적 snapshot인가?', '범위 잠금과 내용 일관성은 다르다', '모든 argument 변경을 계속 막는다', 'arg_lock은 주소 범위 필드를 복사하는 동안입니다. 이후 자료 읽기와 user 변경은 별도 조건입니다.'),
      details=[detail('Setproctitle 경로','원본 주석은 argument 끝 NUL이 덮인 경우 setproctitle 사용을 가정합니다. 기존 범위 내부 NUL이 있으면 거기까지, 없으면 가능한 env 자료를 추가로 읽어 종료를 찾습니다.'),detail('Ref 정리','mm를 얻은 뒤의 조기 종료도 out_mm에서 mmput합니다. Task/mm 참조를 얻는 것과 lock을 잡는 것은 다른 수명·직렬화 기능입니다.')])
    topic('Page 비교·Local Mapping의 역순 해제','메모리','mm/util.c','memcmp_pages',
      '직접 접근하기 어려운 page를 잠시 매핑해 비교하고 local mapping stack을 올바른 순서로 해제합니다.',
      'Generic weak memcmp_pages는 page1과page2를 kmap_local_page로 매핑하고 PAGE_SIZE를 memcmp합니다. 두 번째 주소부터 kunmap_local하고 첫 번째를 해제한 뒤 비교 결과를 반환합니다. Weak 구현이라 architecture가 대체할 수 있습니다.',
      '유효 page 수명과 비교 동안 자료 변경의 동기화를 보장합니다. Local mapping 주소를 저장해 다른 context에서 재사용하지 않습니다. 반환은 같음0·차이부호이며 전체 folio를 한 번에 비교하는 함수가 아닙니다.',
      'map1→map2→memcmp→unmap2→unmap1을 읽으세요.',
      q('첫 매핑을 먼저 해제하도록 순서를 바꿔도 되는가?', 'local mapping의 중첩 계약에 맞춰 역순 해제한다', '항상 아무 순서나 가능하다', '원본은 두 번째 mapping을 먼저 내려놓습니다. Local mapping의 수명과 context 계약을 유지합니다.'),
      q('두 page의 비교 길이는?', 'PAGE_SIZE', '입력 folio 전체 길이를 자동 계산한다', '이 helper는 page 한 개씩 비교합니다. 큰 folio의 모든 자료를 비교하는 길이 계산은 없습니다.'),
      details=[detail('Weak 대체','__weak는 다른 강한 정의로 구현을 바꿀 수 있게 합니다. 이 generic body를 모든 architecture의 machine code라고 계산하지 않습니다.'),detail('주소와 Page','Page metadata pointer와 mapping된 byte 주소는 다릅니다. 실제 byte 비교에는 mapping 주소를 사용하고 그 임시 주소의 lifetime을 지킵니다.')])
    topic('객체 Provenance·Debug 설정과 주소 분류','관찰·디버깅','mm/util.c','mem_dump_obj',
      '문제 pointer의 allocation 출처를 출력할 때 debug 정보의 가용성과 분류 순서를 확인합니다.',
      'CONFIG_PRINTK이면 먼저 kmem_dump_obj, 그다음 vmalloc_dump_obj가 출처를 출력할 수 있는지 시도합니다. 둘 다 못하면 vmalloc 주소·유효 일반 주소·NULL·ZERO_SIZE_PTR·기타 순서로 type 문자열을 선택해 pr_cont합니다. Source 설명은 slab 이름과 debug 설정에 따라 allocation·free stack 정보가 있을 수 있다고 합니다.',
      'Caller가 먼저 적절한 출력 preamble을 기록하고 이 함수로 이어 출력합니다. 정보 가용성이 설정마다 다름을 확인하고 provenance 출력이 pointer 접근의 안전성 검증을 대신한다고 생각하지 않습니다. 관찰한 자료를 수정하거나 allocation을 해제하는 함수는 아닙니다.',
      '두출처시도·주소class순서·pr_cont·CONFIGguard를읽으세요.',
      q('모든 설정에서 마지막 해제의 stack trace가 항상 출력되는가?', 'debug 정보가 있을 때만 가능하다', '모든 pointer에 항상 존재한다', '문서는 정보가 debug 설정과 객체 종류에 따라 다르다고 설명합니다. 출력 부재와 정상 allocation 여부를 동일하게 판단하지 않습니다.'),
      q('이 함수는 발견한 객체를 해제하는가?', '출처를 표시하는 관찰 함수다', '진단 뒤 항상 kfree한다', 'Body는 조회·분류·출력입니다. 수명 변경을 수행하지 않습니다.'),
      details=[detail('출력 이어쓰기','pr_cont를 사용하므로 caller가 앞부분을 출력했다는 계약이 있습니다. 독립적으로 완결된 사용자 문자열을 allocation해서 돌려주는 API가 아닙니다.'),detail('Special Pointer','NULL과ZERO_SIZE_PTR를 분류합니다. 정상 객체처럼 dereference할 수 있는 pointer와 특별한 반환 표현을 구분합니다.')])
    topic('Page Offline·Reader와 전환 Writer의 RW Semaphore','동기화','mm/util.c','page_offline_freeze',
      'Page 내용을 읽는 동안 driver가 접근 불가능 상태로 바꾸는 경쟁을 reader/writer 프로토콜로 막습니다.',
      '공통 page_offline_rwsem에 freeze는 down_read, thaw는 up_read입니다. Driver의 begin은 down_write, end는 up_write입니다. Frozen reader가 있으면 writer의 PageOffline 전환이 기다리고 writer가 전환 중이면 새 reader가 접근 구간에 들어가지 못합니다. Reader들은 공유할 수 있고 writer는 배타적입니다.',
      '자료를 확인하고 읽는 필요한 구간을 freeze/thaw로 감싸고 전환하는 driver는begin/end를 맞춥니다. 이 프로토콜에 참여하지 않는 임의 writer까지 자동 보호하지 않습니다. Page 참조·물리 수명·다른 상태 전환의 lock은 별도로 보장합니다.',
      '공통DECLARE_RWSEM·두read함수·두write함수를연결하세요.',
      q('동시에 여러 freeze reader가 같은 보호 구간에 있을 수 있는가?', 'read lock이라 공유 가능하다', '언제나 한 reader만 가능하다', 'RW semaphore의 read 쪽은 공유합니다. 전환 writer는 그 reader들이 끝나기를 기다립니다.'),
      q('Driver가 begin/end 없이 상태를 바꾸면 freeze가 그 변경도 자동으로 막는가?', '양쪽이 같은 보호 프로토콜을 사용해야 한다', '모든 상태 대입을 hardware가 자동으로 막는다', '보호는 공통 semaphore를 사용하는 읽기·전환 경로의 계약입니다. 단순 변수 대입을 자체적으로 가로채지 않습니다.'),
      details=[detail('문제 상황','원본은 /proc/kcore 같은 PFN walker의 검사 뒤 driver가 page를 offline하여 내용 접근이 위험해지는 경쟁을 설명합니다. 검사와 실제 읽기 사이까지 보호해야 합니다.'),detail('짧은 이름의 역할','Freeze는 상태 bit를 직접 바꾸지 않고 readlock을 잡습니다. Begin도 실제 offline 대입을 하지 않고 전환 구간의 write lock을 제공합니다.')])
    topic('Folio Cache Flush·Architecture Fallback 반복','메모리','mm/util.c','flush_dcache_folio',
      'CPU cache 유지 기능을 page 묶음에 적용할 때 architecture 대체 경로와 실제 반복 단위를 확인합니다.',
      'flush_dcache_folio가 별도로 정의되어 있지 않으면 generic 함수는 folio_nr_pages를 구하고 각 folio_page에 flush_dcache_page를 호출합니다. 한 함수 이름으로 큰 folio를 처리하지만 실제 fallback은 page별 반복입니다. 선택 architecture의 flush 구현이 cache 유지 의미를 정합니다.',
      '유효한 folio와 해당 memory 변경·접근 프로토콜에서 사용합니다. 이름의 flush를 저장장치 fsync·파일 영속화와 동일하게 쓰지 않습니다. Architecture가 제공하면 이 fallback이 선택되지 않습니다.',
      '#ifndefguard·nr·folio_page·각page flush를읽으세요.',
      q('세 page folio의 generic fallback은 하위 flush를 몇 번 호출하는가?', '3번', '언제나 한 번', 'i0부터nr-1까지 각 page에 호출합니다. Folio 묶음과 page 단위를 구분합니다.'),
      q('이 cache flush만으로 파일 내용이 디스크에 영구 저장되는가?', 'CPU cache 유지와 저장장치 영속화는 다르다', '항상 fsync 완료와 동일하다', '하위API는dcache page입니다. Writeback·저장장치flush·파일fsync의계약은별도입니다.'),
      details=[detail('Architecture 선택','Guard가 없으면 다른 구현이 사용될 수 있습니다. Generic 반복을 모든CPU에서 같은instruction으로실행한다고설명하지않습니다.'),detail('수명과 접근','Flush는 folio를 allocation하거나 pin하지 않습니다. 실제 자료 수명·변경 순서·cache coherency 계약은 caller와 architecture 구현을 함께 확인합니다.')])
